from fractions import Fraction as F
from math import factorial as fac

def add_term(out,d,c):
 out[d]=out.get(d,F(0))+c
 if out[d]==0:del out[d]
def deriv(P,j,q):
 out={}
 for d,c in P.items():
  if d[j]<q:continue
  e=list(d);e[j]-=q
  add_term(out,tuple(e),c*F(fac(d[j]),fac(d[j]-q)))
 return out
def moment(p,a,n):
 return F(fac(n),fac(n//p))*a**(n//p) if n%p==0 else F(0)
def cond(P,p,a,S):
 out={}
 for d,c in P.items():
  for i in range(len(d)):
   if i not in S:c*=moment(p,a[i],d[i])
  add_term(out,tuple(d[i] if i in S else 0 for i in range(len(d))),c)
 return out
def heat(P,p,a,j):
 out={}
 for d,c in P.items():
  for k in range(d[j]//p+1):
   e=list(d);e[j]-=p*k
   add_term(out,tuple(e),c*F(fac(d[j]),fac(e[j])*fac(k))*a**k)
 return out
def clamp(P,S):
 return {d:c for d,c in P.items() if all(d[i]==0 for i in range(len(d)) if i not in S)}
def scale(P,c):return {d:v*c for d,v in P.items() if v*c}
checks=corrections=failures=0
for p in [2,4,6,8]:
 for N in [1,2,4]:
  for T in [F(1,2),F(1),F(3,2)]:
   a=[(-1)**(p//2+1)*T/N]*N
   for j in range(N):
    left=set(range(j));right=set(range(j+1))
    for seed in range(24):
     d=tuple((seed*(i+1)+i)%(2*p+3) for i in range(N))
     e=tuple((seed+2*i+1)%(p+2) for i in range(N))
     P={};add_term(P,d,F(2,3));add_term(P,e,F(-3,5))
     for q in range(p+2):
      D=deriv(P,j,q)
      Dnext=deriv(cond(P,p,a,right),j,q)
      assert Dnext==cond(D,p,a,right)
      shifted=scale(clamp(heat(Dnext,p,a[j],j),left),F(1,fac(q)))
      causal=scale(cond(D,p,a,left),F(1,fac(q)))
      assert shifted==causal
      native=scale(clamp(Dnext,left),F(1,fac(q)))
      corrections+=shifted!=native;checks+=1
    x=[0]*N;x[j]=1;x={tuple(x):F(1)}
    assert deriv(cond(x,p,a,left),j,1)=={}
    assert cond(deriv(x,j,1),p,a,left)=={(0,)*N:F(1)}
    failures+=1
print(dict(passed=True,exact_retained_derivative_and_causal_jet_checks=checks,
 nonzero_finite_cell_corrections=corrections,discarded_coordinate_commutation_counterexamples=failures))
